// <auto-generated> by cs/tools/ts2cs.mjs from src/sim/wanderers.ts, then fixed by hand where it says so.
// Wanderers: new survivors arriving by day.
//
// From day 2 a wanderer turns up at ARRIVAL_HOUR at the edge of explored ground,
// a short walk from the colony (on a fully explored map: at the map edge; sim RNG); a second comes at SECOND_ARRIVAL_HOUR if there is a spare bed.
// They wait where they arrived. The player takes them in (they become a
// survivor) or turns them away; ignored for WANDERER_PATIENCE ticks, or still
// waiting at nightfall, they leave on their own.
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class Wanderers
{
    static Wanderers()
    {
        Time.onClock(() => WANDERER_PATIENCE = 3 * Time.TICKS_PER_HOUR);
    }

    public const int ARRIVAL_HOUR = 10;

    /// <summary>How far from a survivor to look for an arrival spot (roughly).</summary>
    public const int ARRIVAL_DISTANCE = 24;

    /// <summary>A second wanderer comes at this hour, but only if there is a spare bed.</summary>
    public const int SECOND_ARRIVAL_HOUR = 14;

    /// <summary>How long a wanderer waits for an answer: 3 in-game hours.</summary>
    public static double WANDERER_PATIENCE = 3 * Time.TICKS_PER_HOUR;

    public static Wanderer? getWanderer(SimState state, string id)
    {
        return state.wanderers.find((w) => w.id == id);
    }

    public static Wanderer addWanderer(SimState state, int x, int y)
    {
        var id = $"v{Js.Str(state.nextId++)}";
        Wanderer w = new() { id = id, traits = Skills.rollTraits(id), name = Survivors.nextSurvivorName(state), x = Js.I(x), y = Js.I(y), leavesTick = state.tick + WANDERER_PATIENCE };
        state.wanderers.push(w);
        return w;
    }

    public static void removeWanderer(SimState state, Wanderer w)
    {
        var i = state.wanderers.indexOf(w);
        if (i >= 0)
        {
            state.wanderers.splice(i, 1);
        }
    }

    /// <summary>Beds nobody would be left without: beds minus survivors minus wanderers already waiting.</summary>
    public static double spareBeds(SimState state)
    {
        var beds = FurnitureMod.ofKind(state, "bed").length;
        return (beds - state.survivors.length) - state.wanderers.length;
    }

    public static void updateWanderers(SimState state)
    {
        reconcileWanderers(state);
        foreach (var w in Js.Iter([.. state.wanderers]))
        {
            if ((state.tick >= w.leavesTick) || Js.T(Time.isNight(state.tick)))
            {
                removeWanderer(state, w);
                Events.logEvent(state, $"{Js.Str(w.name)} gave up waiting and left");
            }
        }
        if (Time.dayOf(state.tick) < 2)
        {
            return;
        }
        var t = Time.tickOfDay(state.tick);
        if (t == (ARRIVAL_HOUR * Time.TICKS_PER_HOUR))
        {
            arrive(state);
        }
        if ((t == (SECOND_ARRIVAL_HOUR * Time.TICKS_PER_HOUR)) && (spareBeds(state) > 0))
        {
            arrive(state);
        }
    }

    /// <summary>A wall built where a wanderer waits moves them to a free neighbour; with none, they leave.</summary>
    public static void reconcileWanderers(SimState state)
    {
        foreach (var w in Js.Iter([.. state.wanderers]))
        {
            if (Js.T(Grids.isWalkable(state.grid, w.x, w.y)))
            {
                continue;
            }
            var to = Pathfinding.DIRS.map((d) => new() { x = Js.I(w.x + d.x), y = Js.I(w.y + d.y) }).find((p) => Js.T(Grids.isWalkable(state.grid, p.x, p.y)));
            if (Js.T(to))
            {
                w.x = Js.I(to.x);
                w.y = Js.I(to.y);
            }
            else
            {
                removeWanderer(state, w);
                Events.logEvent(state, $"{Js.Str(w.name)} was walled out and left");
            }
        }
    }

    /// <summary>Out at the edge of what you've seen, a short walk from someone, on open ground.</summary>
    public static Point? frontierSpot(SimState state, JsSet<string> taken)
    {
        if ((state.survivors.length == 0) || !state.grid.explored.includes(0))
        {
            return null;
        }
        for (var attempt = 0; attempt < 8; attempt++)
        {
            var s = Rng.pick(state, state.survivors);
            var near = new() { x = Js.I(JsMath.max(0, JsMath.min(state.grid.width - 1, s.pos.x + Rng.randomInt(state, -ARRIVAL_DISTANCE, ARRIVAL_DISTANCE + 1)))), y = Js.I(JsMath.max(0, JsMath.min(state.grid.height - 1, s.pos.y + Rng.randomInt(state, -ARRIVAL_DISTANCE, ARRIVAL_DISTANCE + 1)))) };
            bool ok(int x, int y)
            {
                return (Js.T(Fog.isExplored(state, x, y)) && (Grids.getTile(state.grid, x, y) == "floor")) && (Rooms.labelAt(state, x, y) == Rooms.OUTDOORS) && !taken.has($"{Js.Str(x)},{Js.Str(y)}") && Pathfinding.DIRS.some((d) => Js.T(Grids.inBounds(state.grid, x + d.x, y + d.y)) && !Js.T(Fog.isExplored(state, x + d.x, y + d.y)));
            }
            var p = Space.nearestTile(state.grid, near, ok);
            if (Js.T(p))
            {
                return p;
            }
        }
        return null;
    }

    public static void arrive(SimState state)
    {
        var taken0 = Js.Set(state.wanderers.map((w) => $"{Js.Str(w.x)},{Js.Str(w.y)}"));
        var spot = frontierSpot(state, taken0);
        if (Js.T(spot))
        {
            var w = addWanderer(state, spot.x, spot.y);
            Events.logEvent(state, $"{Js.Str(w.name)}, a wanderer, is waiting at ({Js.Str(spot.x)}, {Js.Str(spot.y)}): take them in?");
            return;
        }
        var __d0 = state.grid;
        var width = __d0.width;
        var height = __d0.height;
        List<Point> edge = [];
        for (var x = 0; x < width; x++)
        {
            edge.push(new() { x = Js.I(x), y = Js.I(0) }, new() { x = Js.I(x), y = Js.I(height - 1) });
        }
        for (var y = 1; y < (height - 1); y++)
        {
            edge.push(new() { x = Js.I(0), y = Js.I(y) }, new() { x = Js.I(width - 1), y = Js.I(y) });
        }
        var taken = Js.Set(state.wanderers.map((w) => $"{Js.Str(w.x)},{Js.Str(w.y)}"));
        var candidates = edge.filter((p) => (Grids.getTile(state.grid, p.x, p.y) == "floor") && !taken.has($"{Js.Str(p.x)},{Js.Str(p.y)}"));
        if (candidates.length == 0)
        {
            return;
        }
        var p = Rng.pick(state, candidates);
        var w = addWanderer(state, p.x, p.y);
        Events.logEvent(state, $"{Js.Str(w.name)}, a wanderer, is waiting at ({Js.Str(p.x)}, {Js.Str(p.y)}): take them in?");
    }

    /// <summary>Ticks left before a wanderer gives up (for the UI).</summary>
    public static double patienceLeft(SimState state, Wanderer w)
    {
        return JsMath.max(0, JsMath.min(w.leavesTick - state.tick, Time.DAY_LENGTH));
    }
}
